# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
L=[['拉丁 fungi／fungor；分词词干 funct-','履行、执行、完成职责']]
F=L+[['拉丁 functio → 法语 fonction 等借入路线','执行、履行；某物承担的作用'],['英语 function','功能、职能；活动；起作用']]
A=L+[['两种历史分析：英语 function + -al；或中世纪拉丁 functionalis','两条路线都接“履行、功能”的来源，不互相当作先后阶段'],['英语 functional','与功能有关；能起作用、实用的']]
P=L+[['拉丁 per- + fungi → perfungi','贯穿、完成 + 履行 → 把事情做完'],['晚期拉丁 perfunctorius → 英语 perfunctory','草率地应付过去 → 敷衍的']]
U=L+[['拉丁 fungi vice → 中世纪拉丁 fungibilis','代行某人的位置或作用 → 可互相替代的'],['英语 fungible','同等单位可互换、无须区分个体的']]
def H(h,w,m):return h+[[w,m]]
WA=[
E('function','/ˈfʌŋkʃən/','功能；职能；正式活动；函数；起作用、运转','一个东西或一个人，在整件事里负责做什么，这就是它的 function。','拉丁 fungi“履行、执行”的分词词干 funct- 形成 functio；经法语等路线借入为名词，后来在英语中也作动词。',F,'The function of a lid 是盖子的作用；function as a desk 是当桌子用。a social function 是正式社交活动。数学函数给每个允许的输入指定一个输出；程序里的 function 则是一段可调用来完成任务的代码，不必每次都接收外部输入。','the function of；function as；function properly；attend a function；call a function。','purpose 强调目的，function 强调承担的作用。软件的 feature 是一项用户可见特点；function 还可以指内部函数，范围并不完全相同。',('The main function of the lid is to keep dust out.','盖子的主要作用是挡住灰尘。'),('The old table now functions as a desk.','那张旧桌子现在当书桌用。'),('The function returns the larger of the two numbers.','这个函数返回两个数中较大的一个。'),sources=['https://www.etymonline.com/word/function','https://docs.python.org/3/glossary.html','https://en.wiktionary.org/wiki/function']),
E('functional','/ˈfʌŋkʃənəl/','能正常工作的；实用的；功能方面的','先问“它能不能把该做的事做好”，再谈外观或其他特点。','现代可看作 function + -al；历史解释也包括中世纪拉丁 functionalis，都是“与履行作用有关”。',A,'a functional kitchen 是好用、布局满足需要的厨房；fully functional 表示功能已正常可用。a functional difference 是功能上的区别。医学、数学和编程中另有专门用法，需跟着领域读，不能全部机械翻成“实用”。','fully functional；functional design；functional requirements。','functional 说明能发挥作用或侧重实用；decorative 强调装饰。东西可以既 functional 又 attractive。',('The room is small but functional.','房间虽小，但很实用。'),('The replacement system is now fully functional.','替换后的系统现在已能正常发挥全部功能。'),sources=['https://www.etymonline.com/word/functional','https://en.wiktionary.org/wiki/functional']),
E('functionality','/ˌfʌŋkʃəˈnæləti/','功能性；具备的功能；发挥作用的能力','把产品拿来实际用：它能做哪些事，这些本领合起来就是这里说的 functionality。','functional + -ity；词尾 -al 在接 -ity 后重音移到 /næl/ 附近。',H(A,'英语 functional → functionality','具有功能的 → 功能性、功能集合'),'added functionality 常说增加了可用功能；test the functionality of a device 是检查它的功能是否能实现。谈软件时常用作整体概念，不必总译成拗口的“功能性”；added search functionality 就是增加了搜索功能。','basic functionality；additional functionality；retain functionality。','function 常能数出具体一个功能；functionality 常把能做的事或功能表现作为整体来谈。',('The update adds search functionality to the app.','这次更新给应用增加了搜索功能。'),('We tested the device’s basic functionality before packing it.','打包前，我们测试了设备的基本功能。')),
E('functionally','/ˈfʌŋkʃənəli/','从功能上；就实际作用而言','先把外观、名字放一边，只看它实际完成什么工作。','functional + -ly，表示评价采用功能或实际作用的角度。',H(A,'英语 functional → functionally','从功能或实际作用来看'),'functionally equivalent 说两个东西能完成相同作用，不保证材料、结构和外观一样。functionally separate 说工作上各自负责不同任务，也不一定物理上隔得很远。','functionally equivalent；functionally similar；functionally separate。','physically 看物理形态，functionally 看作用；不同结构也可能在特定任务上功能相近。',('The two buttons look different but are functionally identical.','这两个按钮外观不同，但功能相同。'),('The teams are functionally separate even though they share an office.','这两个团队虽然共用办公室，但职责彼此独立。')),
E('functioning','/ˈfʌŋkʃənɪŋ/','正在运转；能发挥作用的；运作情况','把功能真正用起来：机器在工作，流程在运行。','function 作动词后接 -ing；也可作形容词或名词性成分。',H(F,'英语 function → functioning','发挥作用 → 正在运转、运作情况'),'a functioning clock 是能走时的钟；the functioning of a system 是系统如何运作。说 functioning well 时，well 告诉你运行质量好；只有 functioning，常只是说明它在发挥作用。','functioning properly；a functioning system；the functioning of。','function 是作用或运转这一动作；functioning 更容易突出运行过程和当前状态。',('The cooling system is functioning properly again.','冷却系统又能正常工作了。'),('Clear communication is essential to the functioning of the team.','清楚的沟通对团队运作至关重要。')),
E('nonfunctional','英 /ˌnɒnˈfʌŋkʃənəl/；美 /ˌnɑːnˈfʌŋkʃənəl/','不能起作用的；不具实用功能的；非功能方面的','东西可能还摆在那里，但没有发挥所说的那项作用。','non-“不、非” + functional。',H(A,'英语 non- + functional → nonfunctional','具有功能的 → 不起作用的、非功能方面的'),'a nonfunctional display 可能是不能工作的显示屏，也可能是只作展示的模型，须看语境。软件文档中的 nonfunctional requirements 通常谈性能、可靠性等质量要求；这里不是说这些要求“没用”。','a nonfunctional prototype；a nonfunctional device；nonfunctional requirements。','malfunctioning 常指工作失常；nonfunctional 可以表示根本不能工作，也可能原本就没有实用功能。',('The museum uses a nonfunctional model to show the machine’s shape.','博物馆用一个不能运转的模型展示机器外形。'),('The damaged keyboard is now completely nonfunctional.','损坏的键盘现在完全不能用了。'),sources=['https://en.wiktionary.org/wiki/nonfunctional','https://github.com/microsoft/code-with-engineering-playbook/blob/main/docs/design/design-patterns/non-functional-requirements-capture-guide.md?plain=1']),
E('functionless','/ˈfʌŋkʃənləs/','没有功能的；没有实际作用的','这个部分还在，但在眼前这套系统里找不到它要完成的工作。','function + -less“没有”。',H(F,'英语 function + -less → functionless','作用 → 没有作用的'),'a functionless button 可以是只剩外形、按了也没有任何作用的按钮。说生物结构或复杂制度 functionless 要慎重理解：没有发现功能，与已经证实没有功能，不是一回事。这里是在学这个词表达的判断。','a functionless part；apparently functionless；a functionless ornament。','nonfunctional 常说没能运转；functionless 更突出缺少作用或目的。两者在一些场景会重叠。',('The designer removed a functionless button from the panel.','设计师去掉了面板上一个没有作用的按钮。'),('The model includes two functionless handles for visual detail.','模型带有两个只用于外观细节、没有实际功能的把手。'),sources=['https://en.wiktionary.org/wiki/functionless']),
E('dysfunction','/dɪsˈfʌŋkʃən/','功能失常；运作不良','各个部分还在，却没按应该的方式配合，事情因此卡住或走偏。','dys-“不良、困难、异常” + function。',H(F,'英语 dys- + function → dysfunction','正常发挥作用 → 运作失常'),'医学中可指器官功能异常；组织中也可说互相推诿、沟通失灵带来的 dysfunction。它比一次小失误更容易指向运作方式有问题，但具体程度仍由上下文决定。','organ dysfunction；organisational dysfunction；signs of dysfunction。','dysfunction 常用于身体、关系或组织的运作问题；malfunction 尤其常用于机器设备的故障。',('The report linked the delays to dysfunction within the organisation.','报告把这些延误与组织内部运作失常联系起来。'),('Repeated communication failures revealed a deeper dysfunction.','反复的沟通失败暴露了更深层的运作问题。'),sources=['https://www.etymonline.com/word/dysfunction','https://en.wiktionary.org/wiki/dysfunction']),
E('dysfunctional','/dɪsˈfʌŋkʃənəl/','运作失常的；功能不良的；关系模式有问题的','本来应当互相配合的环节，反而不断制造冲突、阻碍或伤害。','dysfunction + -al；也可看出 dys- 与 functional 的对应关系。',H(F,'英语 dysfunction → dysfunctional','运作失常 → 处于失常状态的'),'a dysfunctional team 可能职责不清、沟通失灵；a dysfunctional relationship 常说相处模式反复出问题。描述的是运作或关系状况，不应据此把一个人的全部价值概括成“坏掉了”。','a dysfunctional organisation；a dysfunctional relationship；become dysfunctional。','inefficient 强调效率低；dysfunctional 更可能涉及基本配合方式有问题，不只是速度慢。',('The committee became dysfunctional when members stopped sharing information.','成员不再共享信息后，委员会的运作出了问题。'),('The novel explores a dysfunctional relationship between two friends.','小说探讨了两个朋友之间一种有问题的相处关系。')),
E('dysfunctionality','/dɪsˌfʌŋkʃəˈnæləti/','功能失常的状态；运作不良','把“这套机制总是配合不好”作为一种状态来讨论。','dysfunctional + -ity，形成性质或状态名词。',H(F,'英语 dysfunction → dysfunctional → dysfunctionality','运作问题 → 运作有问题的 → 这种状态'),'dysfunctionality 常见于较抽象、正式的讨论，可以说制度、团队或关系的失常状态。一般表达中 dysfunction 往往更简洁，不必因为这个词更长就觉得含义更深。','institutional dysfunctionality；the dysfunctionality of a system。','dysfunction 与 dysfunctionality 大量重叠；后者尤其把失常当作一种性质或状态，并不是严重程度自动更高。',('The study examines the dysfunctionality of the old reporting system.','这项研究考察了旧报告系统的运作失常问题。'),('The new process reduced the dysfunctionality caused by unclear responsibilities.','新流程减少了职责不清带来的运作问题。'),sources=['https://en.wiktionary.org/wiki/dysfunctionality']),
E('malfunction','/ˌmælˈfʌŋkʃən/','故障；失灵；发生故障','机器本来该完成某件事，却没有按预期工作。','mal-“坏、不正确” + function；可以作名词，也可以作动词。',H(F,'英语 mal- + function → malfunction','发挥作用 → 工作失常、故障'),'a mechanical malfunction 是机械故障；The sensor malfunctioned 是传感器出了故障。它可以表现为完全不动，也可以是给出错误数据、间歇失灵，不一定只指彻底损坏。','a technical malfunction；equipment malfunction；malfunction during use。','damage 说受到损坏；malfunction 说工作不正常。设备可能外观完好却失灵，也可能受损后仍能工作。',('A sensor malfunction caused the alarm to sound.','传感器故障使警报响了。'),('The printer malfunctioned halfway through the job.','打印机在任务进行到一半时出了故障。'),sources=['https://en.wiktionary.org/wiki/malfunction']),
E('malfunctioning','/ˌmælˈfʌŋkʃənɪŋ/','正在失灵；有故障的；异常运转','故障不是只写在报告里，此刻设备就没有按该有的方式工作。','malfunction + -ing；常作现在分词或修饰设备的形容词。',H(F,'英语 malfunction → malfunctioning','出故障 → 正在失灵、有故障的'),'a malfunctioning lock 是不能正常工作的锁；is malfunctioning 表示正在出现异常。它不自动告诉你故障在哪里，还需要具体描述设备怎样不正常。','a malfunctioning device；a malfunctioning sensor；keep malfunctioning。','malfunction 是故障或出故障；malfunctioning 更容易放在名词前，直接指出哪个东西在失灵。',('The engineer replaced the malfunctioning sensor.','工程师更换了失灵的传感器。'),('One of the displays is malfunctioning and keeps flickering.','其中一块显示屏出了故障，一直闪烁。')),
E('wavefunction','/ˈweɪvˌfʌŋkʃən/','波函数〔物理〕','像一份用于计算量子测量结果的数学描述；它记录的不只是“哪里有多大可能”，还包含相位等信息。','英语 wave“波” + function“函数”；function 的远源仍是拉丁“执行、作用”词族，两部分是在英语中组合的。',[['英语 wave + function','波 + 函数'],['英语 wavefunction','描述量子态的波函数']],'常用希腊字母 ψ 表示。对于归一化的位置波函数，取其模的平方得到位置的概率密度，再对某个区域积分得到在那里测到粒子的概率。初学时先分清：波函数本身与概率密度不是同一个量。','a wavefunction；normalise a wavefunction；the phase of a wavefunction。','wavefunction 包含振幅和相位信息；probability density 是由它计算出的概率密度。不能把波函数简单当成粒子的经典运动轨迹。',('The students plotted the wavefunction and its probability density separately.','学生分别画出了波函数和相应的概率密度。'),('The wavefunction must be normalised before these probabilities are calculated.','计算这些概率之前，必须先把波函数归一化。'),sources=['https://en.wiktionary.org/wiki/wavefunction','https://ocw.mit.edu/courses/8-04-quantum-physics-i-spring-2013/1c7cf0d4019d75c86e9de198b92df100_Ei8CFin00PY.pdf']),
]
